internal sealed class GoogleTokenResponse {public string access_token="",refresh_token="",error="",scope="";public int expires_in=3600;}
internal sealed class DriveRemoteFile {public string id="",name="",mimeType="",webViewLink="",resourceKey="",modifiedTime="";}
internal sealed class DriveFilePage {public List<DriveRemoteFile> files=new List<DriveRemoteFile>();public string nextPageToken="";public bool incompleteSearch;}
internal sealed class DriveAboutUser {public string emailAddress="",displayName="";}
internal sealed class DriveAbout {public DriveAboutUser user;}
internal sealed class GoogleDriveClient {
 internal readonly GoogleVault Vault;static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4*1024*1024};
 internal const string Scope="https://www.googleapis.com/auth/drive.readonly https://www.googleapis.com/auth/calendar.events https://www.googleapis.com/auth/calendar.calendarlist.readonly";
 internal GoogleDriveClient(GoogleVault vault){Vault=vault;}
 internal static string Encode(byte[] data){return Convert.ToBase64String(data).TrimEnd('=').Replace('+','-').Replace('/','_');}
 internal static string Random(){var bytes=new byte[48];using(var rng=new RNGCryptoServiceProvider())rng.GetBytes(bytes);return Encode(bytes);}
 internal static string Challenge(string verifier){using(var sha=SHA256.Create())return Encode(sha.ComputeHash(Encoding.ASCII.GetBytes(verifier)));}
 internal static string Form(IEnumerable<KeyValuePair<string,string>> fields){return String.Join("&",fields.Select(p=>Uri.EscapeDataString(p.Key)+"="+Uri.EscapeDataString(p.Value??"")));}
 internal static string AuthUrl(GoogleClientConfig config,string redirect,string state,string verifier){return "https://accounts.google.com/o/oauth2/v2/auth?"+Form(new Dictionary<string,string>{{"client_id",config.client_id},{"redirect_uri",redirect},{"response_type","code"},{"scope",Scope},{"state",state},{"code_challenge",Challenge(verifier)},{"code_challenge_method","S256"},{"access_type","offline"},{"prompt","consent select_account"}});}
 internal static string Callback(string target,string expectedState){if(!target.StartsWith("/",StringComparison.Ordinal)||target.StartsWith("//",StringComparison.Ordinal))return null;var uri=new Uri("http://127.0.0.1"+target);if(uri.AbsolutePath!="/")return null;var query=System.Web.HttpUtility.ParseQueryString(uri.Query);foreach(string key in new[]{"state","code","error"}){var values=query.GetValues(key);if(values!=null&&values.Length!=1)return null;}string state=query["state"];if(state==null||state.Length!=expectedState.Length)return null;int difference=0;for(int i=0;i<state.Length;i++)difference|=state[i]^expectedState[i];if(difference!=0)return null;if(!String.IsNullOrEmpty(query["error"]))throw new InvalidOperationException("La connexion a été refusée ou annulée dans le navigateur.");string code=query["code"];return String.IsNullOrEmpty(code)||code.Length>4096?null:code;}
 static string ReadTarget(TcpClient client){client.ReceiveTimeout=2000;client.SendTimeout=2000;var stream=client.GetStream();var bytes=new byte[8192];int length=0;while(length<bytes.Length){int count=stream.Read(bytes,length,Math.Min(512,bytes.Length-length));if(count==0)return null;length+=count;string header=Encoding.ASCII.GetString(bytes,0,length);if(header.Contains("\r\n\r\n")){var line=header.Split(new[]{"\r\n"},StringSplitOptions.None)[0].Split(' ');return line.Length==3&&line[0]=="GET"?line[1]:null;}}return null;}
 static void Respond(TcpClient client,bool accepted){try{byte[] html=Encoding.UTF8.GetBytes("<!doctype html><meta charset=\"utf-8\"><title>Mon espace</title><p>"+(accepted?"Connexion reçue. Vous pouvez revenir dans Mon espace.":"Cette réponse ne correspond pas à la connexion en cours.")+"</p>");string header="HTTP/1.1 "+(accepted?"200 OK":"400 Bad Request")+"\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: "+html.Length+"\r\nCache-Control: no-store\r\nContent-Security-Policy: default-src 'none'\r\nConnection: close\r\n\r\n";byte[] head=Encoding.ASCII.GetBytes(header);var stream=client.GetStream();stream.Write(head,0,head.Length);stream.Write(html,0,html.Length);}catch(IOException){}}
 internal static async Task<string> WaitCallback(TcpListener listener,string state,CancellationToken token){using(token.Register(()=>listener.Stop())){for(int i=0;i<100;i++){token.ThrowIfCancellationRequested();TcpClient client;try{client=await listener.AcceptTcpClientAsync();}catch(SocketException){token.ThrowIfCancellationRequested();throw;}catch(ObjectDisposedException){token.ThrowIfCancellationRequested();throw;}using(client){string target;try{target=await Task.Run(()=>ReadTarget(client));}catch(IOException){continue;}if(target==null){Respond(client,false);continue;}string code;try{code=Callback(target,state);}catch(InvalidOperationException){Respond(client,true);throw;}Respond(client,code!=null);if(code!=null)return code;}}}throw new InvalidOperationException("Trop de réponses locales invalides. Relancez la connexion.");}
 static HttpClient Http(){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;return new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(30)};}
 static async Task<GoogleTokenResponse> Tokens(Dictionary<string,string> fields,CancellationToken token){using(var http=Http())using(var response=await http.PostAsync("https://oauth2.googleapis.com/token",new FormUrlEncodedContent(fields),token)){string body=await response.Content.ReadAsStringAsync();if(!response.IsSuccessStatusCode){if(body.Contains("invalid_grant"))throw new InvalidOperationException("La connexion Google a expiré ou a été révoquée. Reconnectez le compte.");throw new InvalidOperationException("Google a refusé l’authentification (code "+(int)response.StatusCode+"). Vérifiez le client OAuth et les comptes de test.");}var result=Json.Deserialize<GoogleTokenResponse>(body);if(result==null||String.IsNullOrEmpty(result.access_token))throw new InvalidDataException("La réponse de connexion Google est incomplète.");return result;}}
 static Dictionary<string,string> ClientFields(GoogleClientConfig config){var fields=new Dictionary<string,string>{{"client_id",config.client_id}};if(!String.IsNullOrEmpty(config.client_secret))fields["client_secret"]=config.client_secret;return fields;}
 internal async Task Connect(Action<string> openBrowser,CancellationToken cancellation){var config=Vault.Read<GoogleClientConfig>("client");if(config==null)throw new InvalidOperationException("Importez d’abord le client OAuth Google de type application de bureau.");string verifier=Random(),state=Random();var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(cancellation)){timeout.CancelAfter(TimeSpan.FromMinutes(5));try{string redirect="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/";var callback=WaitCallback(listener,state,timeout.Token);openBrowser(AuthUrl(config,redirect,state,verifier));string code=await callback;var fields=ClientFields(config);fields["code"]=code;fields["code_verifier"]=verifier;fields["grant_type"]="authorization_code";fields["redirect_uri"]=redirect;var tokens=await Tokens(fields,timeout.Token);if(String.IsNullOrEmpty(tokens.refresh_token))throw new InvalidOperationException("Google n’a pas fourni de connexion persistante. Relancez la connexion et acceptez l’accès.");var session=new GoogleSession{scope=String.IsNullOrEmpty(tokens.scope)?Scope:tokens.scope,access_token=tokens.access_token,refresh_token=tokens.refresh_token,expiresTicks=DateTime.UtcNow.AddSeconds(Math.Max(30,tokens.expires_in)).Ticks};var about=await GetJson<DriveAbout>("about?fields=user(displayName,emailAddress)",session.access_token,timeout.Token);if(about.user!=null){session.email=about.user.emailAddress;session.displayName=about.user.displayName;}timeout.Token.ThrowIfCancellationRequested();Vault.Write("session",session);}finally{timeout.Cancel();listener.Stop();}}}
 readonly SemaphoreSlim accessLock=new SemaphoreSlim(1,1);
 async Task<GoogleSession> Access(bool force,CancellationToken token){await accessLock.WaitAsync(token);try{return await AccessCore(force,token);}finally{accessLock.Release();}}
 async Task<GoogleSession> AccessCore(bool force,CancellationToken token){var session=Vault.Read<GoogleSession>("session");var config=Vault.Read<GoogleClientConfig>("client");if(session==null||config==null)throw new InvalidOperationException("Connectez votre compte Google.");if(force||session.expiresTicks<DateTime.UtcNow.AddMinutes(1).Ticks){var fields=ClientFields(config);fields["refresh_token"]=session.refresh_token;fields["grant_type"]="refresh_token";var refreshed=await Tokens(fields,token);session.access_token=refreshed.access_token;session.expiresTicks=DateTime.UtcNow.AddSeconds(Math.Max(30,refreshed.expires_in)).Ticks;if(!String.IsNullOrEmpty(refreshed.refresh_token))session.refresh_token=refreshed.refresh_token;Vault.Write("session",session);}return session;}
 static async Task<T> GetJson<T>(string path,string access,CancellationToken token){using(var http=Http())using(var request=new HttpRequestMessage(HttpMethod.Get,"https://www.googleapis.com/drive/v3/"+path)){request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",access);using(var response=await http.SendAsync(request,token)){if(response.StatusCode==HttpStatusCode.Unauthorized)throw new UnauthorizedAccessException("Connexion Google à renouveler.");if(!response.IsSuccessStatusCode)throw new InvalidOperationException(response.StatusCode==HttpStatusCode.Forbidden?"Accès Drive refusé : vérifiez l’activation de l’API Drive, les droits du compte et la configuration OAuth.":"Google Drive est indisponible (code "+(int)response.StatusCode+").");return Json.Deserialize<T>(await response.Content.ReadAsStringAsync());}}}
 internal async Task<DriveFilePage> List(string search,bool sheets,string next,CancellationToken token){string path="files?"+Form(new Dictionary<string,string>{{"q",GoogleFiles.Query(search,sheets)},{"fields","nextPageToken,incompleteSearch,files(id,name,mimeType,webViewLink,resourceKey,modifiedTime)"},{"pageSize","50"},{"orderBy","modifiedTime desc"},{"spaces","drive"},{"pageToken",next??""}});var session=await Access(false,token);try{return await GetJson<DriveFilePage>(path,session.access_token,token);}catch(UnauthorizedAccessException){}session=await Access(true,token);return await GetJson<DriveFilePage>(path,session.access_token,token);}

 internal async Task<string> Api(string path,string method,object payload,string etag,CancellationToken token){
  if(!path.StartsWith("calendar/v3/",StringComparison.Ordinal))throw new InvalidDataException("Chemin Google invalide.");
  for(int attempt=0;attempt<2;attempt++){var session=await Access(attempt==1,token);using(var http=Http())using(var request=new HttpRequestMessage(new HttpMethod(method),"https://www.googleapis.com/"+path)){
   request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",session.access_token);if(!String.IsNullOrEmpty(etag))request.Headers.TryAddWithoutValidation("If-Match",etag);if(payload!=null)request.Content=new StringContent(Json.Serialize(payload),Encoding.UTF8,"application/json");
   using(var response=await http.SendAsync(request,token)){if(response.StatusCode==HttpStatusCode.Unauthorized&&attempt==0)continue;if(response.StatusCode==HttpStatusCode.PreconditionFailed)throw new InvalidOperationException("Cet événement a changé dans Google Agenda. Actualisez avant de le modifier.");if(!response.IsSuccessStatusCode)throw new InvalidOperationException(response.StatusCode==HttpStatusCode.Forbidden?"Google Agenda refuse l’accès. Activez Calendar API puis reconnectez le compte pour autoriser les événements.":"Google Agenda est indisponible (code "+(int)response.StatusCode+").");return await response.Content.ReadAsStringAsync();}
  }}throw new UnauthorizedAccessException("Reconnectez votre compte Google.");
 }
 internal async Task<byte[]> Document(string id,string mime,CancellationToken token){
  if(!GoogleFiles.ValidId(id))throw new InvalidDataException("Identifiant Google invalide.");bool native=mime.StartsWith("application/vnd.google-apps.",StringComparison.Ordinal);string path="files/"+Uri.EscapeDataString(id)+(native?"/export?mimeType=application%2Fpdf":"?alt=media");
  for(int attempt=0;attempt<2;attempt++){var session=await Access(attempt==1,token);using(var http=Http())using(var request=new HttpRequestMessage(HttpMethod.Get,"https://www.googleapis.com/drive/v3/"+path)){request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",session.access_token);using(var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,token)){
   if(response.StatusCode==HttpStatusCode.Unauthorized&&attempt==0)continue;if(!response.IsSuccessStatusCode)throw new InvalidOperationException("Le document ne peut pas être lu. Reconnectez Google avec l’autorisation de lecture des documents, et vérifiez son partage (code "+(int)response.StatusCode+").");
   if(response.Content.Headers.ContentLength>50L*1024*1024)throw new InvalidDataException("Document trop volumineux (50 Mo maximum).");using(var input=await response.Content.ReadAsStreamAsync())using(var memory=new MemoryStream()){var buffer=new byte[81920];int count;while((count=await input.ReadAsync(buffer,0,buffer.Length,token))>0){if(memory.Length+count>50L*1024*1024)throw new InvalidDataException("Document trop volumineux.");memory.Write(buffer,0,count);}return memory.ToArray();}
  }}}throw new UnauthorizedAccessException("Reconnectez votre compte Google.");
 }

 internal Task Disconnect(CancellationToken token){token.ThrowIfCancellationRequested();Vault.ClearSession();return Task.FromResult(0);}

 internal static GoogleFilePin Pin(DriveRemoteFile file){if(!GoogleFiles.ValidId(file.id))throw new InvalidDataException("Identifiant de fichier Google invalide.");string url=file.webViewLink;if(!GoogleFiles.ValidUrl(url)){url=file.mimeType=="application/vnd.google-apps.spreadsheet"?"https://docs.google.com/spreadsheets/d/"+file.id+"/edit":file.mimeType=="application/vnd.google-apps.folder"?"https://drive.google.com/drive/folders/"+file.id:"https://drive.google.com/file/d/"+file.id+"/view";}if(!String.IsNullOrEmpty(file.resourceKey)&&url.IndexOf("resourcekey=",StringComparison.OrdinalIgnoreCase)<0){var builder=new UriBuilder(url);var query=System.Web.HttpUtility.ParseQueryString(builder.Query);query["resourcekey"]=file.resourceKey;builder.Query=query.ToString();url=builder.Uri.AbsoluteUri;}string name=String.IsNullOrWhiteSpace(file.name)?"Fichier Google":file.name;return new GoogleFilePin{id=file.id,name=name.Length>200?name.Substring(0,200):name,url=url,mimeType=file.mimeType};}
 static async Task TestLoopback(){var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();using(var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(5))){try{int port=((IPEndPoint)listener.LocalEndpoint).Port;var wait=WaitCallback(listener,"local-test",timeout.Token);using(var client=new TcpClient()){await client.ConnectAsync(IPAddress.Loopback,port);byte[] request=Encoding.ASCII.GetBytes("GET /?state=local-test&code=callback-test HTTP/1.1\r\nHost: 127.0.0.1\r\n\r\n");await client.GetStream().WriteAsync(request,0,request.Length);}if(await wait!="callback-test")throw new Exception("Réception HTTP locale");}finally{listener.Stop();}}var cancelledListener=new TcpListener(IPAddress.Loopback,0);cancelledListener.Start();using(var cancel=new CancellationTokenSource()){var waiting=WaitCallback(cancelledListener,"cancel",cancel.Token);cancel.Cancel();bool cancelled=false;try{await waiting;}catch(OperationCanceledException){cancelled=true;}finally{cancelledListener.Stop();}if(!cancelled)throw new Exception("Annulation du retour OAuth");}}
 internal static void Test(string folder){if(Challenge("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk")!="E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM")throw new Exception("PKCE S256");if(Callback("/?state=expected&code=code-test","expected")!="code-test"||Callback("/?state=wrong&code=test","expected")!=null||Callback("/?state=expected&state=expected&code=test","expected")!=null)throw new Exception("Protection du retour OAuth");bool denied=false;try{Callback("/?state=expected&error=access_denied","expected");}catch(InvalidOperationException){denied=true;}if(!denied)throw new Exception("Refus OAuth ignoré");var pin=Pin(new DriveRemoteFile{id="test",name="Tableau",mimeType="application/vnd.google-apps.spreadsheet",resourceKey="key"});if(!pin.url.Contains("resourcekey=key")||!GoogleFiles.ValidUrl(pin.url))throw new Exception("Lien Sheets");try{Task.Run(async()=>await TestLoopback()).GetAwaiter().GetResult();File.WriteAllText(Path.Combine(folder,"GOOGLE_CALLBACK_CHECK.txt"),"PASS: real loopback HTTP callback and cancellation. No Google account or API call used.");}catch(SocketException){File.WriteAllText(Path.Combine(folder,"GOOGLE_CALLBACK_CHECK.txt"),"SKIPPED: local sockets unavailable in host sandbox.");}}
}
